import { Drawer } from "./Drawer";
import { ActionRow } from "./Button";
import { Chip } from "./KpiCard";
import { RadarChart } from "./charts/radar";
import { RadialGauge } from "./charts/basic";
import { useApp } from "../context/AppContext";
import { Athlete, RADAR_AXES, initials } from "../data/demo";

export function PageHead({ title, desc, actions }: { title: string; desc: string; actions?: React.ReactNode }) {
 return (
 <div className="ci-pagehead ci-fade">
 <div>
 <h1 className="ci-pagehead__title">{title}</h1>
 <p className="ci-pagehead__desc">{desc}</p>
 </div>
 {actions && <div className="ci-pagehead__actions">{actions}</div>}
 </div>
 );
}

export function Insight({ children }: { children?: React.ReactNode }) {
 return (
 <div className="ci-insight">
 <span className="ci-insight__icon"><Icon.brain style={{ width: 16, height: 16 }} /></span>
 <div className="ci-insight__txt">{children}</div>
 </div>
 );
}

export function Toast() {
 const { toastMsg } = useApp();
 if (!toastMsg) return null;
 return (
 <div style={{ position: "fixed", bottom: 24, left: "50%", transform: "translateX(-50%)", zIndex: 95,
 background: "var(--ci-glass-strong)", border: "1px solid var(--ci-border-strong)", borderRadius: 12,
 padding: "11px 18px", fontSize: 12.5, color: "var(--ci-text)", boxShadow: "var(--ci-shadow)",
 backdropFilter: "blur(16px)", display: "flex", alignItems: "center", gap: 10 }} className="ci-fade">
 <span className="ci-dot ci-dot--green" /> {toastMsg}
 </div>
 );
}

const SC: Record<string, string> = { green: "var(--ci-green)", amber: "var(--ci-amber)", red: "var(--ci-red)", cyan: "var(--ci-cyan)" };

export function AthleteDrawer({ athlete, onClose }: { athlete: Athlete | null; onClose: () => void }) {
 const { toast } = useApp();
 if (!athlete) return null;
 const stat = (v: number, l: string) => (
 <div className="ci-stat"><span className="ci-stat__v">{v}</span><span className="ci-stat__l">{l}</span></div>
 );
 return (
 <Drawer open={!!athlete} onClose={onClose} title={athlete.name}
 sub={`${athlete.id} · ${athlete.sport} · ${athlete.region}`}
 footer={<ActionRow actions={["Investigate", "Add to Watchlist", "Recommend Development Plan"]} onAction={a => { toast(`${a} — ${athlete.name}`); }} />}>
 <div style={{ display: "flex", alignItems: "center", gap: 14, marginBottom: 16 }}>
 <div className="ci-ident__av" style={{ width: 52, height: 52, borderRadius: 14, fontSize: 18, background: SC[athlete.status] }}>{initials(athlete.name)}</div>
 <div>
 <div style={{ display: "flex", gap: 6, marginBottom: 6 }}>
 <Chip status={athlete.status}>{athlete.stage}</Chip>
 <Chip status="ghost">{athlete.pathway}</Chip>
 </div>
 <div className="ci-faint" style={{ fontSize: 11.5 }}>Age {athlete.age} · {athlete.gender === "F" ? "Female" : "Male"} · via {athlete.source}</div>
 </div>
 </div>
 {athlete.flag && (
 <div className="ci-insight" style={{ marginBottom: 16 }}>
 <span className="ci-insight__icon"><Icon.alert style={{ width: 15, height: 15 }} /></span>
 <div className="ci-insight__txt"><b>AI flag:</b> {athlete.flag}</div>
 </div>
 )}
 <div style={{ display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: 12, marginBottom: 16 }}>
 {stat(athlete.potential, "CPI")}
 {stat(athlete.benchmark, "Percentile")}
 {stat(athlete.readiness, "Readiness")}
 {stat(athlete.injuryRisk, "Risk %")}
 </div>
 <div style={{ display: "flex", gap: 16, alignItems: "center" }}>
 <RadarChart axes={RADAR_AXES} size={200}
 profiles={[{ label: athlete.name, color: SC[athlete.status], values: RADAR_AXES.map((_, i) => 55 + ((athlete.potential + i * 7) % 45)) },
 { label: "Elite", color: "var(--ci-violet)", values: [82, 85, 80, 78, 84, 76] }]} />
 <RadialGauge value={athlete.wearable} label="Recovery" color="var(--ci-green)" size={110} />
 </div>
 </Drawer>
 );
}
","/* ============================================================
 Executive Command Center — component styles (PREMIUM LIGHT)
 ============================================================ */

/* ---- Compact executive header ---- */
.cc-head { display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; margin-bottom: 12px; }
.cc-head__title { font-size: 19px; font-weight: 800; letter-spacing: 0.01em; margin: 0; line-height: 1.1; }
.cc-head__sub { font-size: 11px; color: var(--ci-cyan); letter-spacing: 0.10em; text-transform: uppercase; margin-top: 3px; font-weight: 700; }
.cc-head__meta { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.cc-pill {
 display: inline-flex; align-items: center; gap: 7px; padding: 5px 10px; border-radius: 999px;
 border: 1px solid var(--ci-border); background: #fff; font-size: 11px; color: var(--ci-text-dim);
}
.cc-pill b { color: var(--ci-text); font-weight: 700; }
.cc-pill--ai { border-color: rgba(10,153,199,0.30); background: var(--ci-cyan-soft); color: var(--ci-cyan); font-weight: 700; }

/* ---- Pipeline connected funnel ---- */
.cc-funnel { position: relative; width: 100%; }
.cc-pipe__legendrow { display: flex; justify-content: space-between; align-items: center; margin-top: 4px; }

/* ---- Cycle readiness ---- */
.cc-cycles { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }
.cc-cycle { border: 1px solid var(--ci-border); border-radius: var(--ci-radius-sm); padding: 11px; cursor: pointer; transition: all .16s ease; background: var(--ci-bg-0); }
.cc-cycle:hover { border-color: var(--ci-cyan); transform: translateY(-2px); box-shadow: var(--ci-shadow-soft); }
.cc-cycle__top { display: flex; align-items: baseline; justify-content: space-between; margin-bottom: 8px; }
.cc-cycle__yr { font-size: 16px; font-weight: 800; }
.cc-cycle__ov { font-size: 11px; font-weight: 800; }

/* ---- Bullet indicator ---- */
.cc-bullet { margin-bottom: 7px; }
.cc-bullet__row { display: flex; justify-content: space-between; font-size: 10px; color: var(--ci-text-dim); margin-bottom: 3px; }
.cc-bullet__track { height: 6px; border-radius: 4px; background: rgba(18,38,78,0.08); position: relative; overflow: hidden; }
.cc-bullet__fill { height: 100%; border-radius: 4px; }

/* ---- Talent map ---- */
.cc-map-wrap { display: flex; gap: 14px; }
.cc-map { flex: 1.35; min-width: 0; }
.cc-mapbox { width: 100%; height: 320px; border-radius: var(--ci-radius-sm); overflow: hidden; border: 1px solid var(--ci-border); position: relative; background: #dfe7f0; }
.cc-map-toggles { display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 8px; }
.cc-snapshot { flex: 1; min-width: 0; border-left: 1px solid var(--ci-border); padding-left: 14px; }
.cc-snap__grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin: 10px 0; }
.cc-snap__v { font-size: 17px; font-weight: 800; color: var(--ci-text); }
.cc-snap__l { font-size: 10px; color: var(--ci-text-faint); text-transform: uppercase; letter-spacing: 0.05em; }

/* Leaflet popups tuned to the light theme */
.leaflet-container { font-family: var(--ci-font); background: #dfe7f0; }
.leaflet-popup-content-wrapper { border-radius: 10px; box-shadow: var(--ci-shadow); }
.leaflet-popup-content { margin: 10px 12px; font-size: 12px; color: var(--ci-text); }
.leaflet-bar a { color: var(--ci-text); }

/* ---- Velocity quadrant ---- */
.cc-quad-note { display: flex; flex-wrap: wrap; gap: 6px 14px; margin-top: 8px; font-size: 10.5px; color: var(--ci-text-faint); }

/* ---- Opportunity cards ---- */
.cc-opp { border: 1px solid var(--ci-border); border-radius: var(--ci-radius-sm); padding: 11px; background: var(--ci-bg-0); display: flex; flex-direction: column; gap: 7px; transition: border-color .15s ease; }
