.cc-state--INPROGRESS { background: var(--ci-amber-soft); color: var(--ci-amber); }
.cc-state--COMPLETED { background: var(--ci-green-soft); color: var(--ci-green); }

/* ---- AI executive insight strip ---- */
.cc-ai { display: grid; grid-template-columns: repeat(4, 1fr) auto; gap: 14px; align-items: stretch; }
.cc-ai__cell { padding-right: 14px; border-right: 1px solid var(--ci-border); }
.cc-ai__cell:last-of-type { border-right: none; }
.cc-ai__k { font-size: 9.5px; font-weight: 800; letter-spacing: 0.12em; color: var(--ci-cyan); text-transform: uppercase; margin-bottom: 5px; display: flex; align-items: center; gap: 6px; }
.cc-ai__v { font-size: 12px; color: var(--ci-text); line-height: 1.4; }
.cc-ai__actions { display: flex; flex-direction: column; gap: 6px; justify-content: center; }
@media (max-width: 1100px) { .cc-ai { grid-template-columns: 1fr 1fr; } .cc-ai__cell { border-right: none; } }

/* ---- Activity stream ---- */
.cc-feed { display: flex; flex-direction: column; }
.cc-feed__item { display: flex; gap: 10px; align-items: flex-start; padding: 8px 0; border-bottom: 1px solid var(--ci-grid-line); }
.cc-feed__item:last-child { border-bottom: none; }
.cc-feed__ic { width: 26px; height: 26px; border-radius: 8px; flex: none; display: grid; place-items: center; }
.cc-feed__tx { font-size: 11.5px; color: var(--ci-text-dim); line-height: 1.35; flex: 1; }
