// ---- Region-derived opportunity metrics ----
const avgDiscovered = REGIONS_T.reduce((s, r) => s + r.discovered, 0) / REGIONS_T.length
export function regionDerived(r: RegionT) {
 const coverage = Math.round((r.assessed / r.discovered) * 100)
 const participationIdx = Math.round((r.discovered / avgDiscovered) * 100)
 const opportunity = Math.max(
 0,
 Math.min(
 100,
 Math.round(
 (participationIdx / 100) * 34 +
 Math.max(0, NATIONAL_CONVERSION_AVG - r.conversion) * 6 +
 Math.max(0, 55 - coverage) * 0.7
 )
 )
 )
 return { coverage, participationIdx, participationVsAvg: participationIdx - 100, opportunity }
}
export function highestOpportunityRegion() {
 return [...REGIONS_T].sort((a, b) => regionDerived(b).opportunity - regionDerived(a).opportunity)[0].key
}

export { REGIONS_T, NATIONAL_CONVERSION_AVG }
","import React from "react";
import { Panel, Counter, Sparkline } from "../../primitives";
import { Chip, Trend } from "../../KpiCard";
import { ActionRow } from "../../Button";
import { Icon, IconName } from "../../Icons";
import { TalentMapLeaflet, MapLayer } from "../../charts/TalentMapLeaflet";
import { RADAR_KPIS, REGIONS_T, NATIONAL_CONVERSION_AVG, regionDerived, highestOpportunityRegion } from "../../../data/radar";
import { useRadar } from "./ctx";

const SC: Record<string, string> = { green: "var(--ci-green)", amber: "var(--ci-amber)", red: "var(--ci-red)", cyan: "var(--ci-cyan)" };

export function RadarKpiStrip() {
 const { toast } = useRadar();
 return (
 <>
 {RADAR_KPIS.map(k => {
 const color = SC[k.status];
 return (
 <div key={k.id} className="ci-panel ci-panel--hover ci-kpi ci-span-2" role="button" tabIndex={0}
 title={k.support} onClick={() => toast(`Drill-down · ${k.label}`)} onKeyDown={e => e.key === "Enter" && toast(k.label)}>
 <span className="ci-kpi__drill"><Icon.chevron style={{ width: 14, height: 14 }} /></span>
 <div className="ci-kpi__top">
 <span className="ci-kpi__label">{k.label}</span>
 <span className="ci-kpi__icon" style={{ background: `${color}22`, color }}>{React.createElement(Icon[(k.icon as IconName)] || Icon.activity)}</span>
 </div>
 <div className="ci-kpi__value">
 <Counter value={k.value >= 1000000 ? k.value / 1000000 : k.value} decimals={k.value >= 1000000 ? 2 : 0} />
 {k.value >= 1000000 && <span className="ci-kpi__unit">M</span>}
 </div>
 <div className="ci-kpi__spark"><Sparkline data={k.spark} color={color} /></div>
 <div className="ci-kpi__foot"><Trend delta={k.delta} /><span className="ci-kpi__bench">{k.support}</span></div>
 </div>
 );
 })}
 </>
 );
}

const LAYERS: { id: MapLayer; label: string }[] = [
 { id: "density", label: "Talent Density" },
 { id: "participation", label: "Participation" },
 { id: "highpotential", label: "High Potential" },
 { id: "assessments", label: "Assessments" },
 { id: "velocity", label: "Dev Velocity" },
];

export function RadarMapRow() {
 const { region, setRegion, open, toast } = useRadar();
 const [layer, setLayer] = React.useState<MapLayer>("density");
 React.useEffect(() => { if (!region) setRegion(highestOpportunityRegion()); }, []);
 return (
 <Panel span={8} hover title="National Talent Map" sub="Saudi Arabia · 13 regions · OpenStreetMap · click a region to cross-filter"
 right={<div className="ci-seg">
 {LAYERS.map(l => <button key={l.id} className={`ci-seg__btn ${layer === l.id ? "ci-seg__btn--active" : ""}`} onClick={() => setLayer(l.id)}>{l.label}</button>)}
 </div>}>
 <div style={{ height: 340 }}>
 <TalentMapLeaflet regions={REGIONS_T} layer={layer} selected={region}
 onSelect={k => { setRegion(k); toast(`Region · ${REGIONS_T.find(r => r.key === k)?.name}`); }} />
 </div>
 </Panel>
 );
}

export function RegionalSnapshot() {
 const { region, open, toast } = useRadar();
 const sel = REGIONS_T.find(r => r.key === region) || REGIONS_T.find(r => r.key === highestOpportunityRegion())!;
 const d = regionDerived(sel);
 return (
 <Panel span={4} hover title="Regional Snapshot" sub={sel.name}
 right={<Chip status={sel.flag}>{sel.conversion}% conv</Chip>}>
 <div className="tr-oppscore">
 <div><div className="tr-oppscore__num">{d.opportunity}</div></div>
 <div>
 <div className="tr-oppscore__lab">Opportunity score</div>
 <div style={{ fontSize: 11, color: "var(--ci-text-dim)", marginTop: 2 }}>
 {d.participationVsAvg > 0 ? `+${d.participationVsAvg}% participation vs avg` : `${d.participationVsAvg}% participation vs avg`} · {d.coverage}% assessed
 </div>
 </div>
 </div>
 <div className="cc-snap__grid">
 <div><div className="cc-snap__v ci-num">{sel.assessed.toLocaleString()}</div><div className="cc-snap__l">Profiles assessed</div></div>
 <div><div className="cc-snap__v ci-num">{sel.highPotential}</div><div className="cc-snap__l">High potential</div></div>
 <div><div className="cc-snap__v ci-num">{sel.pathways.toLocaleString()}</div><div className="cc-snap__l">Dev pathways</div></div>
 <div><div className="cc-snap__v ci-num">{sel.velocity}</div><div className="cc-snap__l">Dev velocity</div></div>
 </div>
 <div style={{ margin: "2px 0 8px" }}>
 <div className="cc-snap__l" style={{ marginBottom: 4 }}>Top sports · fastest-growing <b style={{ color: "var(--ci-cyan)" }}>{sel.fastest}</b></div>
 <div style={{ display: "flex", gap: 5, flexWrap: "wrap" }}>{sel.top3.map((s, i) => <Chip key={s} status={i === 0 ? "cyan" : "ghost"}>{s}</Chip>)}</div>
 </div>
 <div className="ci-insight" style={{ marginBottom: 10 }}>
 <span className="ci-insight__icon">◆</span>
 <div className="ci-insight__txt" style={{ fontSize: 11.5 }}>{sel.insight}
 {sel.conversion < NATIONAL_CONVERSION_AVG && <> <b>({(NATIONAL_CONVERSION_AVG - sel.conversion).toFixed(1)}pts below national avg)</b></>}</div>
 </div>
 <ActionRow actions={["View Athletes", "Create Cohort", "Launch Assessment", "Add to Watchlist"]}
 onAction={a => { if (a === "View Athletes") open("region", sel); else toast(`${a} — ${sel.name}`); }} />
 </Panel>
 );
}
","import React from "react";
import { Source } from "../../data/radar";

// Source mix: bar length = share, green overlay = high-potential yield, number = conversion.
export function SourceMix({ sources, selected, onSelect }:
 { sources: Source[]; selected: string | null; onSelect: (s: string) => void }) {
 const [tip, setTip] = React.useState<{ x: number; y: number; s: Source } | null>(null);
 const maxShare = Math.max(...sources.map(s => s.share));
 return (
 <div style={{ position: "relative", display: "flex", flexDirection: "column", gap: 8 }}>
 {sources.map(s => {
 const sel = selected === s.name, dim = selected && !sel;
 return (
 <div key={s.name} onClick={() => onSelect(sel ? "" : s.name)}
 onMouseMove={e => setTip({ x: e.clientX, y: e.clientY, s })} onMouseLeave={() => setTip(null)}
 style={{ cursor: "pointer", opacity: dim ? 0.45 : 1, transition: "opacity .15s" }}>
 <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11.5, marginBottom: 3 }}>
 <span style={{ fontWeight: 700, color: sel ? "var(--ci-cyan)" : "var(--ci-text)" }}>{s.name}</span>
 <span className="ci-faint">{s.share}% · <b style={{ color: "var(--ci-blue)" }}>{s.conversion}%</b> conv · <b style={{ color: "var(--ci-green)" }}>{s.yield}%</b> yield</span>
 </div>
 <div style={{ position: "relative", height: 9, borderRadius: 5, background: "rgba(18,38,78,0.07)", overflow: "hidden" }}>
 <div style={{ position: "absolute", left: 0, top: 0, height: "100%", width: `${(s.share / maxShare) * 100}%`,
 borderRadius: 5, background: "rgba(10,153,199,0.35)" }} />
 <div style={{ position: "absolute", left: 0, top: 0, height: "100%", width: `${(s.share / maxShare) * (s.yield / 20) * 100}%`,
 borderRadius: 5, background: "var(--ci-green)" }} title="High-potential yield" />
 </div>
 </div>
 );
 })}
