const gapTone = (g: number) => (g >= -10 ? "var(--ci-green)" : g >= -16 ? "var(--ci-amber)" : "var(--ci-red)");
const SC: Record<string, string> = { green: "var(--ci-green)", amber: "var(--ci-amber)", red: "var(--ci-red)", cyan: "var(--ci-cyan)" };

export function CohortExplorerRow() {
 const { region, sport, source, open, toast } = useRadar();
 const [f, setF] = React.useState({ age: false, top: false, fast: false, notElite: false });
 const regionName = REGIONS_T.find(r => r.key === region)?.name;

 const rows = COHORT.filter(a => {
 if (regionName && a.region !== regionName) return false;
 if (sport && a.sport !== sport) return false;
 if (source && a.source !== source) return false;
 if (f.age && !(a.age >= 16 && a.age <= 21)) return false;
 if (f.top && a.nationalPct < 90) return false;
 if (f.fast && a.velocity < 80) return false;
 if (f.notElite && a.stage === "Elite") return false;
 return true;
 });
 const chip = (k: keyof typeof f, label: string) => (
 <span className={`tr-chip ${f[k] ? "tr-chip--on" : ""}`} onClick={() => setF(s => ({ ...s, [k]: !s[k] }))}>{label}</span>
 );

 return (
 <Panel span={7} hover title="Cohort Explorer"
 sub={`${rows.length} athletes${regionName ? " · " + regionName : ""}${sport ? " · " + sport : ""}${source ? " · " + source : ""}`}
 right={<Button size="sm" variant="primary" icon="plus" onClick={() => { toast(`Cohort created · ${rows.length} athletes`); open("coh", { title: "New Cohort", count: rows.length }); }}>Create Cohort</Button>}>
 <div className="tr-builder">
 {chip("age", "Age 16–21")}
 {chip("top", "Top 10% national")}
 {chip("fast", "Velocity > 75")}
 {chip("notElite", "Not yet elite")}
 </div>
 <div style={{ maxHeight: 260, overflowY: "auto" }}>
 <table className="ci-table tr-table">
 <thead><tr>
 <th>Athlete</th><th>Age</th><th>Sport</th><th>Region</th>
 <th>Local</th><th>Nat'l</th><th>Global gap</th><th>Vel</th><th>Stage</th>
 </tr></thead>
 <tbody>
 {rows.map(a => (
 <tr key={a.id} onClick={() => open("athlete", a)}>
 <td className="ci-table__name">{a.name}</td>
 <td className="ci-num">{a.age}</td>
 <td>{a.sport}</td>
 <td>{a.region}</td>
 <td className="ci-num tr-pct">P{a.localPct}</td>
 <td className="ci-num tr-pct">P{a.nationalPct}</td>
 <td className="ci-num" style={{ color: gapTone(a.globalGap), fontWeight: 700 }}>{a.globalGap}%</td>
 <td className="ci-num" style={{ color: a.velocity >= 80 ? "var(--ci-green)" : "var(--ci-text-dim)" }}>{a.velocity}</td>
 <td><Chip status="ghost">{a.stage}</Chip></td>
 </tr>
 ))}
 {rows.length === 0 && <tr><td colSpan={9} className="ci-faint" style={{ textAlign: "center", padding: 18 }}>No athletes match the current filters.</td></tr>}
 </tbody>
 </table>
 </div>
 </Panel>
 );
}

const NEXT: Record<string, string> = { NEW: "ASSIGNED", ASSIGNED: "IN PROGRESS", "IN PROGRESS": "COMPLETED", COMPLETED: "COMPLETED" };
const stateClass = (s: string) => "cc-state cc-state--" + s.replace(/\s/g, "");

export function ActionQueueRow() {
 const { toast, region } = useRadar();
 const [items, setItems] = React.useState<TalentAction[]>(TALENT_ACTIONS);
 const advance = (id: string) => setItems(it => it.map(a => a.id === id ? (() => { const ns = NEXT[a.state]; toast(`${a.title} → ${ns}`); return { ...a, state: ns }; })() : a));
 return (
 <Panel span={5} hover title="Assessment / Action Queue" sub="Discovery-driven actions · advance to change state">
 <div style={{ display: "flex", flexDirection: "column", gap: 7 }}>
 {items.map(a => {
 const rel = region && a.region === region;
 return (
 <div key={a.id} className="cc-act" style={rel ? { borderColor: "var(--ci-cyan)", background: "var(--ci-cyan-soft)" } : undefined}>
 <span className="ci-dot" style={{ background: SC[a.pri], boxShadow: `0 0 6px ${SC[a.pri]}`, flex: "none" }} />
 <div className="cc-act__body">
 <div className="cc-act__title">{a.title}</div>
 <div className="cc-act__meta">{a.cohort} · {a.owner}</div>
 </div>
 <span className={stateClass(a.state)}>{a.state}</span>
 <Button size="sm" variant={rel ? "primary" : "ghost"}
 onClick={() => advance(a.id)}>{a.state === "NEW" ? "Assign" : a.state === "ASSIGNED" ? "Start" : a.state === "IN PROGRESS" ? "Complete" : "Open"}</Button>
 </div>
 );
 })}
 </div>
 </Panel>
 );
}
","import React from "react";
import { Drawer } from "../../Drawer";
import { ActionRow } from "../../Button";
import { Chip } from "../../KpiCard";
import { RadarChart } from "../../charts/radar";
import { RDrawerState } from "./ctx";
import { BENCH_AXES, GLOBAL_BENCHMARK, regionDerived, NATIONAL_CONVERSION_AVG } from "../../../data/radar";

const stat = (v: React.ReactNode, l: string) => (
 <div className="ci-stat"><span className="ci-stat__v">{v}</span><span className="ci-stat__l">{l}</span></div>
);
const gapTone = (g: number) => (g >= -10 ? "var(--ci-green)" : g >= -16 ? "var(--ci-amber)" : "var(--ci-red)");

export function RadarDrawer({ state, onClose, onAction }:
 { state: RDrawerState | null; onClose: () => void; onAction: (a: string) => void }) {
 if (!state) return null;
 const { kind, data } = state;
 let title = "", sub = "", body: React.ReactNode = null, actions: string[] = [];

 if (kind === "region") {
 const d = regionDerived(data);
 title = data.name + " Region"; sub = `${data.discovered.toLocaleString()} discovered · opportunity ${d.opportunity}`;
 body = <>
 <div style={{ display: "grid", gridTemplateColumns: "repeat(2,1fr)", gap: 12, marginBottom: 14 }}>
 {stat(data.assessed.toLocaleString(), "Assessed")}
 {stat(data.highPotential, "High potential")}
 {stat(data.pathways.toLocaleString(), "Dev pathways")}
 {stat(`${d.coverage}%`, "Assessment coverage")}
 </div>
 <div className="ci-eyebrow" style={{ marginBottom: 6 }}>Top 3 sports · fastest {data.fastest}</div>
 <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 12 }}>{data.top3.map((s: string, i: number) => <Chip key={s} status={i === 0 ? "cyan" : "ghost"}>{s}</Chip>)}</div>
 <div className="ci-insight"><span className="ci-insight__icon">◆</span><div className="ci-insight__txt" style={{ fontSize: 12 }}>{data.insight}
 {data.conversion < NATIONAL_CONVERSION_AVG && <> <b>({(NATIONAL_CONVERSION_AVG - data.conversion).toFixed(1)}pts below national average)</b></>}</div></div>
 </>;
 actions = ["View Athletes", "Create Cohort", "Launch Assessment", "Add to Watchlist"];
 } else if (kind === "athlete") {
 title = data.name; sub = `${data.sport} · ${data.region} · age ${data.age}`;
 body = <>
 <div style={{ display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: 12, marginBottom: 14 }}>
 {stat("P" + data.localPct, "Local pct")}
 {stat("P" + data.nationalPct, "National pct")}
 {stat(<span style={{ color: gapTone(data.globalGap) }}>{data.globalGap}%</span>, "Global gap")}
 </div>
 {data.attrs && <RadarChart axes={BENCH_AXES} size={230}
 profiles={[{ label: data.name, color: "#0a99c7", values: data.attrs }, GLOBAL_BENCHMARK]} />}
 {!data.attrs && <p className="ci-dim" style={{ fontSize: 12.5, lineHeight: 1.5 }}>{data.velocity >= 80 ? "Improving faster than cohort — strong candidate for accelerated assessment." : "Tracking within expected development band."} Current stage: <b style={{ color: "var(--ci-text)" }}>{data.stage}</b>.</p>}
 </>;
 actions = ["Open Athlete", "Compare", "Add to Watchlist", "Request Assessment"];
 } else if (kind === "opp") {
 title = data.tag; sub = "Talent opportunity";
 body = <>
 <div className="cc-opp__signal" style={{ marginBottom: 8 }}>{data.signal}</div>
 <p className="ci-dim" style={{ fontSize: 12.5, lineHeight: 1.5 }}>{data.why}</p>
 </>;
 actions = data.actions.concat(["Investigate"]);
 } else if (kind === "coh") {
 title = data.title || "Cohort"; sub = data.count != null ? `${data.count} athletes` : "Discovery cohort";
 body = <p className="ci-dim" style={{ fontSize: 12.5, lineHeight: 1.5 }}>Save this cohort to track, compare and progress the selected athletes together, or request a batch assessment.</p>;
 actions = ["Add to Watchlist", "Request Assessment", "Create Intervention"];
 }

 return (
 <Drawer open onClose={onClose} title={title} sub={sub}
 footer={<ActionRow actions={actions} onAction={onAction} />}>{body}</Drawer>
 );
}
