 actions={cross
 ? <Button icon="x" variant="ghost" onClick={() => { setSport(null); setSource(null); toast("Cleared cross-filters"); }}>Clear filters</Button>
 : <Button icon="brain" variant="primary" onClick={() => toast("Ask AI — where should we launch discovery?")}>Ask AI</Button>} />
