const SC: Record<string, string> = { green: "var(--ci-green)", amber: "var(--ci-amber)", red: "var(--ci-red)", cyan: "var(--ci-cyan)" };

export function AthleteTable({ rows, onSelect, columns = ["cpi", "percentile", "readiness", "risk", "momentum"] }:
 { rows: Athlete[]; onSelect: (a: Athlete) => void; columns?: string[] }) {
