 WEARABLES, WEARABLE_HEADLINE, CV_MODES, CV_METRICS, CV_POSE, CV_BONES,
 PHYSICAL, TECHNICAL, COMPETITION, MILESTONES, NEXT_MILESTONE, AI_INSIGHTS,
 INTERVENTIONS, NEXT_BEST, COMPARE_TARGETS, Attr, Intervention,
} from "../../data/athlete360";

const SC: Record<string, string> = { green: "var(--ci-green)", amber: "var(--ci-amber)", red: "var(--ci-red)", cyan: "var(--ci-cyan)" };
const rTone = (v: number) => (v >= 80 ? "var(--ci-green)" : v >= 65 ? "var(--ci-cyan)" : "var(--ci-amber)");

function AttrBar({ a }: { a: Attr }) {
 return (
 <div className="a360-attr">
 <span className="a360-attr__label">{a.label}</span>
 <div className="a360-attr__bar" title={`${a.label}: ${a.level} · P${a.percentile} · gap ${a.gap}`}>
 <div className="a360-attr__fill" style={{ width: `${a.level}%` }} />
 <div className="a360-attr__gap" style={{ left: `${a.level - a.gap}%` }} title="Global benchmark" />
 </div>
 <span className="a360-attr__pct">P{a.percentile} <span style={{ color: a.trend >= 0 ? "var(--ci-green)" : "var(--ci-red)" }}>{a.trend >= 0 ? "▲" : "▼"}</span></span>
 </div>
 );
}

export function Athlete360() {
 const { toast } = useApp();
 const [compare, setCompare] = React.useState<string | null>(null);
 const [cvMode, setCvMode] = React.useState("Sprint");
 const [drawer, setDrawer] = React.useState<{ title: string; sub?: string; body: React.ReactNode; actions: string[] } | null>(null);

 const dnaProfiles = [DNA.athlete, DNA.national, DNA.global].concat(compare === "Another athlete" ? [DNA.compareAthlete] : []);

 const openCompare = () => setDrawer({
 title: "Compare against", sub: "Overlay a reference on the profile",
 body: <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
 {COMPARE_TARGETS.map(t => (
 <button key={t} className="ci-btn ci-btn--ghost" style={{ justifyContent: "flex-start" }}
 onClick={() => { setCompare(t); setDrawer(null); toast(`Comparing vs ${t}`); }}>{t}</button>
 ))}
 </div>, actions: [],
 });

 const openIntervention = (v: Intervention) => setDrawer({
 title: v.reason, sub: `${v.date} · ${v.owner}`,
 body: <>
 <div style={{ display: "flex", gap: 8, marginBottom: 12 }}><Chip status={v.status}>{v.status === "green" ? "Resolved" : "Active"}</Chip><Chip status="ghost">{v.outcome}</Chip></div>
 <p className="ci-dim" style={{ fontSize: 12.5, lineHeight: 1.5 }}>Intervention led by {v.owner}. Outcome: <b style={{ color: "var(--ci-text)" }}>{v.outcome}</b>.</p>
 </>, actions: ["Open Assessment", "Track Outcome", "Create Intervention"],
 });

 return (
 <div className="ci-fade">
 {/* HERO */}
 <div className="a360-hero">
 <div className="a360-photo">{PROFILE.initials}</div>
 <div className="a360-id">
 <div className="a360-id__name">{PROFILE.name}</div>
 <div className="a360-id__meta">{PROFILE.sport} · {PROFILE.discipline} · age {PROFILE.age} · {PROFILE.region}<br />{PROFILE.team}</div>
 <div className="a360-id__chips">{PROFILE.chips.map(c => <Chip key={c.label} status={c.s}>{c.label}</Chip>)}</div>
 </div>
 <div className="a360-hero__stats">
 <div className="a360-stat"><div className="a360-stat__v" style={{ color: "var(--ci-cyan)" }}>P{PROFILE.nationalPct}</div><div className="a360-stat__l">National</div></div>
 <div className="a360-stat"><div className="a360-stat__v" style={{ color: "var(--ci-green)" }}>-{PROFILE.globalGap}%</div><div className="a360-stat__l">Global gap</div></div>
 <div className="a360-stat"><div className="a360-stat__v">{PROFILE.velocity}</div><div className="a360-stat__l">Dev velocity</div></div>
 <div className="a360-stat"><div className="a360-stat__v" style={{ color: rTone(PROFILE.readiness) }}>{PROFILE.readiness}%</div><div className="a360-stat__l">Readiness</div></div>
 </div>
 <div className="a360-hero__actions">
 <Button variant="primary" icon="layers" onClick={openCompare}>Compare</Button>
 <Button icon="watch" onClick={() => toast("Added to watchlist")}>Add to Watchlist</Button>
 <Button icon="target" onClick={() => toast("Assessment requested")}>Request Assessment</Button>
 <Button icon="plus" onClick={() => toast("Intervention created")}>Create Intervention</Button>
 <Button icon="journey" onClick={() => toast("Development plan created")}>Create Development Plan</Button>
 </div>
 </div>

 {compare && <div className="a360-cmp"><Icon.layers style={{ width: 14, height: 14 }} /> Comparing against <b>{compare}</b>
 <button className="ci-btn ci-btn--ghost ci-btn--sm" style={{ marginLeft: "auto" }} onClick={() => setCompare(null)}>Clear</button></div>}

 <div className="ci-grid">
 {/* ROW 1 */}
 <Panel span={4} hover title="Readiness" sub={`Overall ${READINESS.overall}%`}
 right={<RadialGauge value={READINESS.overall} label="" color={rTone(READINESS.overall)} size={54} />}>
 <div style={{ marginTop: 2 }}>{READINESS.dims.map(d => <Bullet key={d.label} label={d.label} value={d.value} />)}</div>
 <div className="ci-insight" style={{ marginTop: 8 }}><span className="ci-insight__icon"><Icon.brain style={{ width: 14, height: 14 }} /></span>
 <div className="ci-insight__txt" style={{ fontSize: 11.5 }}>{READINESS.note}</div></div>
 </Panel>

 <Panel span={4} hover title="Development DNA" sub="Athlete vs national top vs global benchmark">
 <RadarChart axes={DNA_AXES} size={240} profiles={dnaProfiles} />
 </Panel>

 <Panel span={4} hover title="Benchmark Position" sub="Where the athlete sits nationally & globally">
 <div style={{ display: "flex", gap: 14, alignItems: "center", marginBottom: 6 }}>
 <div><div style={{ fontSize: 26, fontWeight: 800, color: "var(--ci-cyan)" }}>P{PROFILE.nationalPct}</div><div className="cc-snap__l">National percentile</div></div>
 <div><div style={{ fontSize: 26, fontWeight: 800, color: "var(--ci-green)" }}>-{PROFILE.globalGap}%</div><div className="cc-snap__l">Global gap</div></div>
 </div>
 <Distribution marker={PROFILE.nationalPct} height={92} />
 <div style={{ marginTop: 6 }}>
 <BenchmarkBars data={PHYSICAL.slice(0, 4).map(a => ({ label: a.label, you: a.level, intl: a.level - a.gap }))} />
 </div>
 </Panel>

 {/* ROW 2 */}
 <Panel span={6} hover title="Performance Trajectory" sub="Is the athlete moving toward the elite benchmark? · toggle series in legend">
 <TrendCurve labels={TRAJ_AGES} height={224} series={TRAJ_SERIES} />
 <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginTop: 2 }}>
 {TRAJ_MARKERS.map(m => <span key={m.label} className="ci-faint" style={{ fontSize: 10.5 }}><b style={{ color: "var(--ci-cyan)" }}>◆</b> {TRAJ_AGES[m.m]}: {m.label}</span>)}
 </div>
 </Panel>

 <Panel span={3} hover title="Wearable Intelligence" sub="Meaningful changes only"
 right={<Trend delta={WEARABLE_HEADLINE.delta} />}>
 <div className="ci-insight" style={{ marginBottom: 8, borderColor: "rgba(217,130,10,0.28)", background: "var(--ci-amber-soft)" }}>
 <span className="ci-insight__icon" style={{ color: "var(--ci-amber)" }}><Icon.alert style={{ width: 14, height: 14 }} /></span>
 <div className="ci-insight__txt" style={{ fontSize: 11 }}><b style={{ color: "var(--ci-amber)" }}>{WEARABLE_HEADLINE.label}:</b> {WEARABLE_HEADLINE.note}</div>
 </div>
 {WEARABLES.map(w => (
 <div key={w.label} className="a360-wear">
 <div className="a360-wear__l"><div className="a360-wear__lab">{w.label}</div><div className="a360-wear__val">{w.value}</div></div>
 <div className="a360-wear__spark"><Sparkline data={w.spark} color={SC[w.status]} h={22} /></div>
 <span style={{ fontSize: 11, fontWeight: 700, color: w.delta >= 0 ? (w.status === "amber" ? "var(--ci-amber)" : "var(--ci-green)") : "var(--ci-amber)", width: 34, textAlign: "right" }}>{w.delta >= 0 ? "+" : ""}{w.delta}%</span>
 </div>
 ))}
 <div style={{ marginTop: 8 }}><ActionRow actions={["Investigate", "Create Intervention"]} onAction={a => toast(a)} /></div>
 </Panel>

 <Panel span={3} hover title="Computer Vision" sub={cvMode + " analysis"}
 right={<div className="ci-seg">{CV_MODES.slice(0, 2).map(m => <button key={m} className={`ci-seg__btn ${cvMode === m ? "ci-seg__btn--active" : ""}`} onClick={() => setCvMode(m)}>{m}</button>)}</div>}>
 <svg viewBox="0 0 100 100" className="ci-chart" style={{ maxWidth: 150, margin: "0 auto", display: "block" }}>
 {CV_BONES.map(([a, b], i) => <line key={i} x1={CV_POSE[a][0]} y1={CV_POSE[a][1]} x2={CV_POSE[b][0]} y2={CV_POSE[b][1]} stroke="var(--ci-cyan)" strokeWidth="1.6" strokeOpacity="0.6" />)}
 {CV_POSE.map((p, i) => <circle key={i} cx={p[0]} cy={p[1]} r="2.4" fill="var(--ci-cyan)" />)}
 </svg>
 <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 5, marginTop: 6 }}>
 {CV_METRICS.slice(0, 4).map(m => (
 <div key={m.label} style={{ fontSize: 10.5 }}><span className="ci-faint">{m.label}</span><div style={{ fontWeight: 800, color: SC[m.tone] }}>{m.value}{m.unit}</div></div>
 ))}
 </div>
 <div style={{ marginTop: 8 }}><Button size="sm" variant="ghost" onClick={() => toast("Opening full CV analysis")}>Full Analysis</Button></div>
 </Panel>

 {/* ROW 3 */}
 <Panel span={7} hover title="Physical & Technical Profile" sub="Level · percentile · trend · benchmark gap (violet marker)">
 <div style={{ display: "flex", gap: 18 }}>
 <div style={{ flex: 1, minWidth: 0 }}>
 <div className="ci-eyebrow" style={{ marginBottom: 8 }}>Physical</div>
 {PHYSICAL.map(a => <AttrBar key={a.label} a={a} />)}
 </div>
 <div style={{ flex: 1, minWidth: 0, borderLeft: "1px solid var(--ci-border)", paddingLeft: 16 }}>
 <div className="ci-eyebrow" style={{ marginBottom: 8 }}>Technical</div>
 {TECHNICAL.map(a => <AttrBar key={a.label} a={a} />)}
 </div>
 </div>
 </Panel>

 <Panel span={5} hover title="Competition & Exposure" sub="Current international exposure vs recommended"
 right={<Button size="sm" variant="ghost" icon="medal" onClick={() => toast("Competition plan recommended")}>Recommend Plan</Button>}>
 <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11.5, marginBottom: 4 }}>
 <span className="ci-dim">International exposure</span><span><b style={{ color: "var(--ci-amber)" }}>{COMPETITION.exposure}%</b> <span className="ci-faint">/ target {COMPETITION.target}%</span></span>
 </div>
 <div className="a360-expo" style={{ marginBottom: 12 }}>
 <div className="a360-expo__fill" style={{ width: `${COMPETITION.exposure}%` }} />
 <div className="a360-expo__target" style={{ left: `${COMPETITION.target}%` }} title="Target" />
 </div>
 <div className="ci-eyebrow" style={{ marginBottom: 6 }}>Exposure by level</div>
 {COMPETITION.levels.map(l => (
 <div key={l.label} style={{ marginBottom: 6 }}>
 <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11, marginBottom: 2 }}><span className="ci-dim">{l.label}</span><span className="ci-num">{l.value}%</span></div>
 <div className="ci-meter"><div className="ci-meter__fill" style={{ width: `${l.value}%`, background: SC[l.status] }} /></div>
 </div>
 ))}
 <hr className="ci-divider" />
 <div className="ci-eyebrow" style={{ marginBottom: 6 }}>Recent results</div>
 {COMPETITION.history.slice(0, 3).map(h => (
 <div key={h.event} style={{ display: "flex", justifyContent: "space-between", fontSize: 11.5, padding: "3px 0" }}>
 <span className="ci-dim">{h.event} <span className="ci-faint">· {h.level}</span></span><span style={{ fontWeight: 600 }}>{h.result}</span>
 </div>
 ))}
 </Panel>

 {/* ROW 3b — Development Journey */}
 <Panel span={12} hover title="Development Journey"
 right={<Chip status="amber">Next · {NEXT_MILESTONE}</Chip>}>
 <div className="a360-mile">
 {MILESTONES.map((m, i) => (
 <div key={m.key} className="a360-mile__step">
 {i < MILESTONES.length - 1 && <span className={`a360-mile__line ${m.done ? "a360-mile__line--done" : ""}`} />}
 <div className={`a360-mile__dot ${m.done ? "a360-mile__dot--done" : ""} ${m.next ? "a360-mile__dot--next" : ""}`}>
 {m.done && <Icon.target style={{ width: 10, height: 10, color: "#fff" }} />}
 </div>
 <div className="a360-mile__label">{m.label}</div>
 <div className="a360-mile__date">{m.date}</div>
 <div className="a360-mile__note">{m.note}</div>
 </div>
 ))}
 </div>
 </Panel>

 {/* ROW 4 */}
 <div className="ci-span-5">
 <div className="a360-nba">
 <div className="a360-nba__k">Next Best Action</div>
 <div className="a360-nba__title">{NEXT_BEST.title}</div>
 <div className="a360-nba__why"><b>Why:</b> {NEXT_BEST.why}</div>
 <div className="a360-nba__ev">
 {NEXT_BEST.evidence.map(([l, v]) => <div key={l} className="a360-ev"><div className="a360-ev__v">{v}</div><div className="a360-ev__l">{l}</div></div>)}
 </div>
 <ActionRow actions={NEXT_BEST.actions} onAction={a => { if (a === "View Evidence") setDrawer({ title: "Evidence", sub: NEXT_BEST.title, body: <ul style={{ margin: 0, paddingLeft: 16 }}>{NEXT_BEST.evidence.map(([l, v]) => <li key={l} className="ci-dim" style={{ fontSize: 12.5, marginBottom: 4 }}>{l}: <b style={{ color: "var(--ci-text)" }}>{v}</b></li>)}</ul>, actions: ["Create Competition Plan", "Track Outcome"] }); else toast(a); }} />
 </div>
 </div>

 <Panel span={4} hover title="AI Athlete Insights" sub="Signal → action">
 <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
 {AI_INSIGHTS.map(it => (
 <div key={it.id} className="cc-opp">
 <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
 <span className="ci-dot" style={{ background: SC[it.status], boxShadow: `0 0 8px ${SC[it.status]}` }} />
 <span className="ci-eyebrow" style={{ color: SC[it.status] }}>{it.tag}</span>
 </div>
 <div className="cc-opp__signal">{it.signal}</div>
 <Button size="sm" variant="primary" onClick={() => toast(it.action)}>{it.action}</Button>
 </div>
 ))}
 </div>
 </Panel>

 <Panel span={3} hover title="Intervention History" sub="Click for detail">
 {INTERVENTIONS.map(v => (
 <div key={v.id} className="a360-int" onClick={() => openIntervention(v)}>
 <div className="a360-int__rail"><span className="a360-int__dot" style={{ background: SC[v.status] }} /></div>
 <div>
 <div className="a360-int__reason">{v.reason}</div>
 <div className="a360-int__meta">{v.date} · {v.owner} · {v.outcome}</div>
 </div>
 </div>
 ))}
 </Panel>
 </div>

 {drawer && (
 <Drawer open onClose={() => setDrawer(null)} title={drawer.title} sub={drawer.sub}
 footer={drawer.actions.length ? <ActionRow actions={drawer.actions} onAction={a => { toast(a + " — started"); setDrawer(null); }} /> : undefined}>
 {drawer.body}
 </Drawer>
 )}
 </div>
 );
}
","import React from "react";
import { Panel } from "../primitives";
import { Chip } from "../KpiCard";
import { PageHead, Insight } from "../common";
import { Button } from "../Button";
import { AthleteTable } from "../AthleteTable";
import { TrendCurve, BenchmarkBars, RadialGauge } from "../charts/basic";
import { RadarChart } from "../charts/radar";
import { CohortMatrix } from "../charts/matrix";
import { useApp } from "../../context/AppContext";
import { ATHLETES, RADAR_AXES, BENCHMARKS, COHORT, PATHWAYS, Athlete } from "../../data/demo";

const MONTHS = ["Jan", "Mar", "May", "Jul", "Sep", "Nov"];

export function Performance({ onAthlete }: { onAthlete: (a: Athlete) => void }) {
 const { toast } = useApp();
 return (
 <div className="ci-fade">
 <PageHead title="Performance Intelligence" desc="Understand what's driving performance change across the pool — trends, comparative benchmarks and cohort conversion."
 actions={<Button icon="layers" onClick={() => toast("Comparison mode")}>Compare</Button>} />
 <div style={{ marginBottom: 14 }}><Insight>Power output is <b>+5% above international benchmark</b>, but recovery index lags by 18% — the clearest limiter on podium conversion.</Insight></div>
 <div className="ci-grid">
 <Panel span={8} hover title="Performance Index Trend" sub="Composite output vs recovery">
 <TrendCurve labels={MONTHS} series={[
 { name: "Output", color: "#35e0ff", data: [70, 74, 78, 82, 85, 88] },
 { name: "Recovery", color: "#34e3a4", data: [66, 64, 68, 65, 70, 72] },
 ]} height={220} />
 </Panel>
 <Panel span={4} hover title="Benchmark vs International"><BenchmarkBars data={BENCHMARKS} /></Panel>
 <Panel span={5} hover title="Conversion by Cohort" sub="Stage × pathway"><CohortMatrix rows={COHORT} cols={PATHWAYS} onCell={(r, c, v) => toast(`${r}·${c}: ${v}`)} /></Panel>
 <Panel span={7} hover title="Performance Leaders" right={<Chip status="cyan">Top output</Chip>}>
 <AthleteTable rows={[...ATHLETES].sort((a, b) => b.potential - a.potential).slice(0, 5)} onSelect={onAthlete} columns={["cpi", "readiness", "momentum"]} />
 </Panel>
 </div>
 </div>
 );
}

export function Wearables({ onAthlete }: { onAthlete: (a: Athlete) => void }) {
 const { toast } = useApp();
 const risk = [...ATHLETES].filter(a => a.injuryRisk > 45).sort((a, b) => b.injuryRisk - a.injuryRisk).slice(0, 6);
 return (
 <div className="ci-fade">
 <PageHead title="Wearables" desc="Live physiological telemetry — recovery, training load and injury-risk signals streamed from athlete devices."
 actions={<Chip status="green">1,204 devices live</Chip>} />
 <div className="ci-grid">
 <Panel span={3} hover title="Squad Recovery"><RadialGauge value={74} label="avg recovery" color="var(--ci-green)" /></Panel>
 <Panel span={3} hover title="Avg Readiness"><RadialGauge value={81} label="readiness" color="var(--ci-cyan)" /></Panel>
 <Panel span={6} hover title="Load vs Recovery (7-day)" sub="Squad rolling average">
 <TrendCurve labels={["M", "T", "W", "T", "F", "S", "S"]} series={[
 { name: "Load", color: "#ffc24b", data: [40, 62, 55, 78, 70, 48, 30] },
 { name: "Recovery", color: "#34e3a4", data: [72, 68, 70, 60, 62, 74, 80] },
 ]} height={180} />
 </Panel>
 <Panel span={12} hover title="Injury-Risk Watch" sub="Athletes with elevated acute:chronic load"
 right={<Button size="sm" variant="ghost" onClick={() => toast("Escalated to medical")}>Escalate all</Button>}>
 <AthleteTable rows={risk} onSelect={onAthlete} columns={["risk", "readiness", "momentum"]} />
 </Panel>
 </div>
 </div>
 );
}

export function ComputerVision() {
 const { toast } = useApp();
 const KP = [[50, 12], [50, 26], [38, 34], [62, 34], [30, 48], [70, 48], [50, 44], [42, 66], [58, 66], [40, 88], [60, 88]];
 return (
 <div className="ci-fade">
 <PageHead title="Computer Vision" desc="Automated biomechanical analysis from video — movement efficiency, symmetry and technique scoring."
 actions={<Button icon="eye" variant="primary" onClick={() => toast("New capture queued")}>Analyze Capture</Button>} />
 <div className="ci-grid">
 <Panel span={4} hover title="Pose Estimation" sub="Sprint start · 240fps">
 <svg viewBox="0 0 100 100" className="ci-chart" style={{ maxWidth: 220, margin: "0 auto" }}>
 {[[1, 6], [1, 2], [1, 3], [2, 4], [3, 5], [1, 0], [0, 7], [0, 8], [7, 9], [8, 10]].map(([a, b], i) =>
 <line key={i} x1={KP[a][0]} y1={KP[a][1]} x2={KP[b][0]} y2={KP[b][1]} stroke="var(--ci-cyan)" strokeWidth="1.5" strokeOpacity="0.6" />)}
 {KP.map((p, i) => <circle key={i} cx={p[0]} cy={p[1]} r="2.2" fill="var(--ci-cyan)" style={{ filter: "drop-shadow(0 0 3px var(--ci-cyan))" }} />)}
 </svg>
 <div style={{ textAlign: "center", marginTop: 6 }}><Chip status="green">Symmetry 94%</Chip></div>
 </Panel>
 <Panel span={4} hover title="Technique Profile"><RadarChart axes={["Drive", "Symmetry", "Cadence", "Posture", "Extension", "Contact"]} size={210}
 profiles={[{ label: "Athlete", color: "#35e0ff", values: [88, 94, 76, 82, 70, 85] }, { label: "Model", color: "#9a7bff", values: [90, 92, 88, 86, 84, 88] }]} /></Panel>
 <Panel span={4} hover title="Movement Metrics">
 {[["Ground contact", 92, "green"], ["Stride efficiency", 78, "amber"], ["Joint symmetry", 94, "green"], ["Power transfer", 71, "amber"]].map(([l, v, c]: any) => (
 <div key={l} style={{ marginBottom: 12 }}>
 <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11.5, marginBottom: 3 }}><span className="ci-dim">{l}</span><span className="ci-num">{v}</span></div>
 <div className="ci-meter"><div className="ci-meter__fill" style={{ width: `${v}%`, background: `var(--ci-${c})` }} /></div>
 </div>
 ))}
 <Insight>Stride efficiency is the primary improvement lever — <b>+6% projected</b> with cue correction.</Insight>
 </Panel>
 </div>
 </div>
 );
}
","import React from "react";
import { Panel } from "../primitives";
import { Chip } from "../KpiCard";
import { PageHead, Insight } from "../common";
import { Button } from "../Button";
import { TrendCurve, RadialGauge, BenchmarkBars } from "../charts/basic";
import { AthleteTable } from "../AthleteTable";
import { useApp } from "../../context/AppContext";
import { ATHLETES, Athlete } from "../../data/demo";

const WK = ["W1", "W2", "W3", "W4", "W5", "W6"];

export function GymEquipment({ onAthlete }: { onAthlete: (a: Athlete) => void }) {
 const { toast } = useApp();
 return (
 <div className="ci-fade">
 <PageHead title="Gym / Equipment" desc="Strength, conditioning and equipment utilisation across national training centres."
 actions={<Button icon="activity" variant="primary" onClick={() => toast("Logging new gym session")}>Log Session</Button>} />
 <div style={{ marginBottom: 14 }}><Insight>Squat 1RM trending <b>+7% over 6 weeks</b> for the elite strength cohort; equipment utilisation peaking mid-week.</Insight></div>
 <div className="ci-grid">
 <Panel span={3} hover title="Avg Strength Index"><RadialGauge value={82} label="composite 1RM" color="var(--ci-cyan)" /></Panel>
 <Panel span={3} hover title="Equipment Utilisation"><RadialGauge value={68} label="capacity used" color="var(--ci-green)" /></Panel>
 <Panel span={6} hover title="Strength Progression" sub="Squat / bench / deadlift index">
 <TrendCurve labels={WK} height={180} series={[
 { name: "Squat", color: "#0a99c7", data: [70, 72, 75, 76, 80, 82] },
 { name: "Bench", color: "#12a06d", data: [64, 66, 66, 69, 71, 73] },
 { name: "Deadlift", color: "#7c5cff", data: [72, 74, 77, 79, 81, 84] },
 ]} />
 </Panel>
 <Panel span={7} hover title="Strength Leaders" right={<Chip status="cyan">Top composite</Chip>}>
 <AthleteTable rows={[...ATHLETES].sort((a, b) => b.readiness - a.readiness).slice(0, 5)} onSelect={onAthlete} columns={["readiness", "cpi", "momentum"]} />
 </Panel>
 <Panel span={5} hover title="Load vs Benchmark"><BenchmarkBars data={[
 { label: "Squat 1RM", you: 88, intl: 84 }, { label: "Power clean", you: 74, intl: 86 },
 { label: "Vertical jump", you: 81, intl: 79 }, { label: "Sprint power", you: 77, intl: 88 },
 ]} /></Panel>
 </div>
 </div>
